{"function": "() => {
    const winners = [];
    const articles = document.querySelectorAll('article');
    articles.forEach(article => {
        const text = article.textContent.trim();
        // pattern: "2024" Samuel Seungwon Lee South Korea
        const match = text.match(/"(\d{4})"\s*([^0-9]+)\s*([A-Za-z\s]+)/);
        if (match) {
            const year = match[1];
            const name = match[2].trim();
            const nationality = match[3].trim();
            winners.push({year, name, nationality});
        } else {
            // try splitting lines
            const lines = text.split('\n').map(l => l.trim()).filter(l => l);
            if (lines.length >= 2) {
                const year = lines[0].replace(/"/g, '');
                const name = lines[1];
                const nationality = lines[2] || '';
                winners.push({year, name, nationality});
            }
        }
    });
    return winners;
}"}

