        // Find name: heading level 2
        const nameHeading = article.querySelector('h2');
        const name = nameHeading ? nameHeading.textContent.trim() : '';
        // Find nationality: generic after heading that contains country name
        // The nationality appears as a generic sibling after heading
        const nationalityEl = Array.from(article.querySelectorAll('generic')).find(el => {
            const text = el.textContent.trim();
            return text && text !== year && text !== name && !/^\d{4}$/.test(text);
        });
        const nationality = nationalityEl ? nationalityEl.textContent.trim() : '';
        data.push({year, name, nationality});
