from html.parser import HTMLParser

class MalkoParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_row = False
        self.in_cell = False
        self.current_row = []
        self.winners = []
        self.headers = []
        self.cell_data = ""
        self.current_tag = ""

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            # Check if it's a wikitable (based on the HTML snippet)
            for attr_name, attr_value in attrs:
                if attr_name == 'class' and 'wikitable' in attr_value:
                    self.in_table = True
        elif self.in_table and tag == 'tr':
            self.in_row = True
            self.current_row = []
        elif self.in_row and tag in ['td', 'th']:
            self.in_cell = True
            self.current_tag = tag
            self.cell_data = ""

    def handle_endtag(self, tag):
        if tag == 'table' and self.in_table:
            self.in_table = False
        elif self.in_table and tag == 'tr' and self.in_row:
            self.in_row = False
            if self.current_row:
                if self.headers and self.current_row != self.headers:
                    # This is a data row (not header)
                    self.winners.append(self.current_row.copy())
        elif self.in_row and tag in ['td', 'th'] and self.in_cell:
            self.in_cell = False
            if self.cell_data.strip():
                self.current_row.append(self.cell_data.strip())

    def handle_data(self, data):
        if self.in_cell:
            self.cell_data += data

